style:
.tw-zitang.resume-paper {
  color: #2b2636;
}

.tw-zitang.resume-paper .paper-header {
  position: relative;
  display: block;
  margin: 0 0 6.5mm;
  padding: 0 0 4.5mm;
  border: none;
  border-bottom: 1px solid #ebe5f4;
}

.tw-zitang.resume-paper .paper-header::before {
  content: "";
  position: absolute;
  top: calc(var(--paper-mt, 15mm) * -1);
  left: calc(var(--paper-ml, 15mm) * -1);
  right: calc(var(--paper-mr, 15mm) * -1);
  height: 2.2mm;
  background: linear-gradient(90deg, #6d4fa1 0%, #9b82c8 58%, #c0aede 100%);
  print-color-adjust: exact;
}

.tw-zitang.resume-paper .paper-header__main {
  padding-right: 34mm;
}

.tw-zitang.resume-paper .paper-photo {
  position: absolute;
  top: 0;
  right: 0;
  width: 27mm;
  height: 35mm;
  border: 0.5mm solid #e2d8f2;
  border-radius: 1mm;
  box-shadow: none;
  print-color-adjust: exact;
}

.tw-zitang.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #f4effa;
  color: #6d4fa1;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 600;
}

.tw-zitang.resume-paper .paper-name {
  color: #33254f;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.02);
  letter-spacing: 0.06em;
}

.tw-zitang.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #74668a;
}

.tw-zitang.resume-paper .paper-role {
  margin-top: 1.3mm;
  color: #6d4fa1;
  font-weight: 600;
}

.tw-zitang.resume-paper .paper-role::before {
  content: "求职意向：";
  color: #8d81a1;
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-zitang.resume-paper .paper-contacts--labeled {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.3mm 8mm;
  margin-top: 3mm;
  padding-top: 2.8mm;
  border-top: 1px solid #f0eaf7;
  color: #3d3449;
  font-size: calc(var(--paper-base-size) * 0.88);
}

.tw-zitang.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-zitang.resume-paper .paper-contact__label {
  color: #877d96;
}

.tw-zitang.resume-paper .paper-section .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  padding: 1.4mm 3mm;
  background: #f0eaf8;
  border-radius: 1mm;
  color: #4b3573;
  font-size: calc(var(--paper-base-size) * 1);
  letter-spacing: 0.1em;
  print-color-adjust: exact;
}

.tw-zitang.resume-paper .paper-section .paper-section__icon {
  display: grid;
  place-items: center;
  width: 5mm;
  height: 5mm;
  border: none;
  border-radius: 50%;
  background: #6d4fa1;
  color: #fff;
}

.tw-zitang.resume-paper .paper-section .paper-section__icon svg {
  width: 58%;
  height: 58%;
}

.tw-zitang.resume-paper .paper-section .paper-section__title::after {
  content: none;
}

.tw-zitang.resume-paper .paper-section .paper-section__body {
  margin-top: 2.3mm;
  color: #332c3d;
}

.tw-zitang.resume-paper .paper-section .paper-item-title {
  color: #2c2140;
}

.tw-zitang.resume-paper .paper-section .paper-item-period {
  color: #6f6283;
  font-weight: 600;
}

.tw-zitang.resume-paper .paper-section .paper-item-sub {
  color: #4c435a;
}

.tw-zitang.resume-paper .paper-section .paper-note__tag {
  color: #6d4fa1;
}

.tw-zitang.resume-paper .paper-section .paper-skill {
  border-bottom-color: #ece6f4;
}

.tw-zitang.resume-paper .paper-section .paper-skill__level {
  color: #6d4fa1;
}

.tw-zitang.resume-paper .paper-footer {
  border-top: 1px solid #ebe5f4;
  color: #7b7089;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-zitang.resume-paper .paper-rich ul[data-list],
.tw-zitang.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-zitang.resume-paper .paper-rich ul[data-list] > li,
.tw-zitang.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-zitang.resume-paper .paper-rich ul[data-list] > li::before,
.tw-zitang.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-zitang.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-zitang.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-zitang.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-zitang.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-zitang.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-zitang.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-zitang.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-zitang.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-zitang.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-zitang.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-zitang.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-zitang.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-zitang.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-zitang.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-zitang.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-zitang.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-zitang.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-zitang.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-zitang.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-zitang.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-zitang.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-zitang.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-zitang.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-zitang.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
